@extends('layouts.app')@section('content')<div class="container-fluid px-3 px-xl-4 py-4">@include('transport._nav')<h1>Alertas de Transporte</h1><table class="table"><tr><th>Prioridad</th><th>Alerta</th><th>Estado</th><th>Detectada</th><th></th></tr>@foreach($alerts as $a)<tr><td>{{$a->severity==='critical'?'Crítica':'Atención'}}</td><td><b>{{$a->title}}</b><br>{{$a->message}}</td><td>{{$a->status}}</td><td>{{$a->last_detected_at->format('d/m/Y H:i')}}</td><td>@if($a->status==='open')<form class="d-inline" method="POST" action="{{route('transport.alerts.acknowledge',$a)}}">@csrf @method('PUT')<button class="btn btn-sm btn-primary">Reconocer</button></form><form class="d-inline" method="POST" action="{{route('transport.alerts.dismiss',$a)}}">@csrf @method('PUT')<button class="btn btn-sm btn-secondary">Descartar</button></form>@endif</td></tr>@endforeach</table>{{$alerts->links()}}</div>@endsection
